style.css:
@-moz-document domain("youtube.com"), domain("music.youtube.com") {
:root,
  html,
  body,
  html[dark],
  html[darker-dark-theme],
  [dark],
  [darker-dark-theme],
  ytd-app,
  ytd-shorts,
  ytd-engagement-panel-section-list-renderer,
  ytd-popup-container,
  ytd-masthead {
    --liquid-blur: blur(22px) saturate(150%);
    --liquid-blur-sm: blur(12px) saturate(140%);

    --card-radius: 12px;
    --thumb-radius: 9px;
    --panel-radius: 16px;

    /* Warm Pearl -> Clear Glass -> Silver Quartz -> Deep Obsidian */
    --liquid-card-gradient: linear-gradient(
      135deg,
      rgba(255, 250, 242, 0.15) 0%,
      rgba(220, 228, 240, 0.05) 26%,
      rgba(16, 17, 22, 0.34) 52%,
      rgba(255, 238, 214, 0.09) 78%,
      rgba(8, 9, 13, 0.58) 100%
    );

    /* Smoked Quartz Gradient for Menus, Search Suggestions & Comment Drawers */
    --liquid-popup-gradient: linear-gradient(
      155deg,
      rgba(38, 37, 40, 0.72) 0%,
      rgba(20, 21, 26, 0.64) 42%,
      rgba(30, 29, 32, 0.68) 76%,
      rgba(10, 11, 15, 0.86) 100%
    );

    /* AT REST: Sculpted 3D Glass Bevel */
    --liquid-3d-rest:
      inset 0 1.5px 1px 0 rgba(255, 252, 245, 0.36),
      inset 0 -1px 1px 0 rgba(255, 248, 238, 0.05),
      inset 0 0 0 1px rgba(255, 248, 238, 0.12),
      inset 0 8px 16px -8px rgba(255, 246, 232, 0.07),
      0 8px 22px -6px rgba(0, 0, 0, 0.65);

    /* POPUP & PLAYER DEPTH */
    --liquid-popup-depth:
      inset 0 1.5px 1px 0 rgba(255, 252, 245, 0.42),
      inset 0 0 0 1px rgba(255, 248, 238, 0.14),
      0 22px 48px rgba(0, 0, 0, 0.88);

    /* ON HOVER / FOCUS: Luminous 3D Specular Rim + Warm Pearl Halo */
    --liquid-3d-hover:
      inset 0 2px 2px 0 rgba(255, 254, 250, 0.85),
      inset 0 -1px 2px 0 rgba(255, 245, 230, 0.16),
      inset 0 0 0 1px rgba(255, 248, 236, 0.32),
      inset 0 10px 22px -6px rgba(255, 245, 225, 0.14),
      0 16px 34px -6px rgba(0, 0, 0, 0.85),
      0 0 20px rgba(255, 242, 220, 0.12);

    /* Unmask all native YouTube solid surface tokens globally */
    --yt-spec-base-background: transparent !important;
    --yt-spec-raised-background: transparent !important;
    --yt-spec-menu-background: transparent !important;
    --yt-spec-general-background-a: transparent !important;
    --yt-spec-general-background-b: transparent !important;
    --yt-spec-general-background-c: transparent !important;
    --yt-spec-brand-background-primary: transparent !important;
    --yt-spec-brand-background-secondary: transparent !important;
    --yt-spec-additive-background: rgba(255, 250, 242, 0.08) !important;
    --yt-spec-badge-chip-background: rgba(255, 250, 242, 0.08) !important;
    --paper-listbox-background-color: transparent !important;
    --paper-menu-background-color: transparent !important;
    --paper-dialog-background-color: transparent !important;

    /* Core Red Branding */
    --yt-spec-brand-background-solid: #ff0000 !important;
    --yt-spec-brand-button-background: #ff0000 !important;
    --yt-spec-static-brand-red: #ff0000 !important;
    --yt-button-color: #ff3636 !important;
    --yt-spec-themed-blue: #ff0000 !important;
  }

  /* Deep Obsidian Base Canvas */
  html, body {
    background-color: #050507 !important;
  }

  /* --- 2. PROPORTIONAL HEADER GLASS & PRECISION 10PX EDGE-TUCK --- */
  #frosted-glass.ytd-app,
  #frosted-glass.with-chipbar.ytd-app {
    display: none !important;
  }

  /* Clear opaque backgrounds from page-level wrappers */
  ytd-app,
  #page-manager,
  ytd-browse,
  ytd-watch-flexy,
  ytd-search,
  ytd-two-column-browse-results-renderer,
  #primary.ytd-two-column-browse-results-renderer,
  #secondary.ytd-two-column-browse-results-renderer,
  #header.ytd-two-column-browse-results-renderer,
  ytd-tabbed-page-header,
  #wrapper.tp-yt-app-header-layout,
  tp-yt-app-header,
  #contentContainer.tp-yt-app-header,
  #page-header-container.ytd-tabbed-page-header,
  #page-header.ytd-tabbed-page-header,
  #page-header-banner.ytd-tabbed-page-header,
  yt-page-header-renderer,
  yt-page-header-view-model,
  .ytPageHeaderViewModelHost,
  .page-header-view-model-wiz,
  ytd-c4-tabbed-header-renderer,
  #channel-container.ytd-c4-tabbed-header-renderer,
  #channel-header.ytd-c4-tabbed-header-renderer,
  ytd-feed-filter-chip-bar-renderer {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border: none !important;
  }

  /* Ambient Light Engine */
  ytd-app::before {
    content: "";
    position: fixed;
    top: 0;
    right: 0;
    bottom: 0;
    left: 0;
    pointer-events: none;
    z-index: 0;
    background:
      radial-gradient(circle at 20% 25%, rgba(255, 242, 222, 0.07) 0%, transparent 55%),
      radial-gradient(circle at 80% 75%, rgba(210, 220, 238, 0.06) 0%, transparent 55%);
    transform: translateZ(0);
  }

  /* Keep ytd-masthead parent free of backdrop-filter so search suggestions blur properly */
  #masthead-container.ytd-app,
  ytd-masthead,
  #container.ytd-masthead,
  #background.ytd-masthead {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    box-shadow: none !important;
  }

  /* MASTHEAD FROSTED LAYER (0px to 56px):
     Blurs scrolling thumbnails behind the Search bar with ZERO downward shadow
     so it never darkens the "All / Gaming / Music" filter chips below it! */
  ytd-masthead::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    height: 56px;
    pointer-events: none;
    z-index: -1;
    background: rgba(5, 5, 7, 0.70) !important;
    backdrop-filter: var(--liquid-blur) !important;
    -webkit-backdrop-filter: var(--liquid-blur) !important;
    box-shadow: none !important;
    border-bottom: none !important;
  }

  /* CHIP BAR FROSTED LAYER (56px to 112px):
     Matches the exact 0.70 obsidian glass of the masthead above it and casts a
     tight 10px negative-spread tuck shadow (never covers video titles below it) */
  #chips-wrapper.ytd-feed-filter-chip-bar-renderer,
  #tabs-inner-container.ytd-c4-tabbed-header-renderer,
  #tabs-container.ytd-c4-tabbed-header-renderer {
    background: linear-gradient(
      180deg,
      rgba(5, 5, 7, 0.70) 0%,
      rgba(5, 5, 7, 0.58) 100%
    ) !important;
    backdrop-filter: var(--liquid-blur) !important;
    -webkit-backdrop-filter: var(--liquid-blur) !important;
    border: none !important;
    box-shadow:
      -72px 0 0 0 rgba(5, 5, 7, 0.65),
      0 10px 18px -8px rgba(0, 0, 0, 0.72) !important;
  }

  ytd-mini-guide-renderer.ytd-app {
    background: transparent !important;
    backdrop-filter: none !important;
  }

  /* --- 3. GRID LOCK & OUTER CARD WRAPPER RESET --- */
  @media (min-width: 1200px) {
    ytd-rich-grid-renderer {
      --ytd-rich-grid-items-per-row: 4 !important;
      --ytd-rich-grid-slim-items-per-row: 6 !important;
    }
  }

  #page-manager ytd-rich-item-renderer,
  #page-manager ytd-rich-item-renderer > #content,
  #page-manager ytd-rich-grid-media,
  #page-manager ytd-reel-item-renderer {
    padding: 0 !important;
    border: none !important;
    background: transparent !important;
    box-shadow: none !important;
    box-sizing: border-box !important;
  }

  yt-touch-feedback-shape .yt-spec-touch-feedback-shape__fill,
  yt-touch-feedback-shape .yt-spec-touch-feedback-shape__stroke {
    background: transparent !important;
    border: none !important;
  }

  /* --- 4. 3D LIQUID GLASS CARDS & SMOOTH EMERGENCE ANIMATION --- */
  @keyframes LiquidCardEmerge {
    0% {
      opacity: 0;
      transform: translateY(10px) scale(0.99);
    }
    100% {
      opacity: 1;
      transform: translateY(0) scale(1);
    }
  }

  #page-manager ytd-rich-grid-media > #dismissible,
  #page-manager ytd-rich-item-renderer .yt-lockup-view-model-wiz,
  #page-manager ytd-horizontal-card-list-renderer .yt-lockup-view-model-wiz,
  #page-manager ytd-item-section-renderer ytd-video-renderer,
  #page-manager ytd-item-section-renderer .yt-lockup-view-model-wiz,
  #page-manager ytd-playlist-video-renderer,
  #page-manager ytd-compact-video-renderer,
  #page-manager ytm-shorts-lockup-view-model-v2,
  #page-manager ytm-shorts-lockup-view-model {
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    background-position: 0% 0% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border-radius: var(--card-radius) !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
    animation: LiquidCardEmerge 0.32s cubic-bezier(0.16, 1, 0.3, 1) backwards;
    transition:
      transform 0.28s cubic-bezier(0.16, 1, 0.3, 1),
      background-position 0.45s cubic-bezier(0.16, 1, 0.3, 1),
      box-shadow 0.28s cubic-bezier(0.16, 1, 0.3, 1) !important;
    position: relative;
    box-sizing: border-box !important;
  }

  #page-manager ytd-rich-item-renderer:hover ytd-rich-grid-media > #dismissible,
  #page-manager ytd-rich-item-renderer:hover .yt-lockup-view-model-wiz,
  #page-manager ytd-horizontal-card-list-renderer .yt-lockup-view-model-wiz:hover,
  #page-manager ytd-item-section-renderer ytd-video-renderer:hover,
  #page-manager ytd-item-section-renderer .yt-lockup-view-model-wiz:hover,
  #page-manager ytd-playlist-video-renderer:hover,
  #page-manager ytd-compact-video-renderer:hover,
  #page-manager ytm-shorts-lockup-view-model-v2:hover,
  #page-manager ytm-shorts-lockup-view-model:hover {
    transform: translateY(-4px) !important;
    background-position: 100% 100% !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  ytd-thumbnail #thumbnail.ytd-thumbnail,
  .yt-thumbnail-view-model,
  .yt-thumbnail-view-model__image,
  ytm-shorts-lockup-view-model-v2 .shortsLockupViewModelHostThumbnailContainer,
  ytm-shorts-lockup-view-model .shortsLockupViewModelHostThumbnailContainer {
    border-radius: var(--thumb-radius) !important;
    border: none !important;
    overflow: hidden !important;
  }

  ytd-thumbnail #thumbnail.ytd-thumbnail img,
  .yt-core-image--content-mode-scale-aspect-fill,
  .yt-thumbnail-view-model__image img,
  ytm-shorts-lockup-view-model-v2 .shortsLockupViewModelHostThumbnailContainer img,
  ytm-shorts-lockup-view-model .shortsLockupViewModelHostThumbnailContainer img {
    border-radius: var(--thumb-radius) !important;
    transition: transform 0.38s cubic-bezier(0.16, 1, 0.3, 1), filter 0.3s ease !important;
  }

  ytd-rich-item-renderer:hover ytd-thumbnail #thumbnail.ytd-thumbnail img,
  ytd-rich-item-renderer:hover .yt-thumbnail-view-model__image img,
  ytd-video-renderer:hover ytd-thumbnail #thumbnail.ytd-thumbnail img,
  .yt-lockup-view-model-wiz:hover .yt-thumbnail-view-model__image img,
  ytd-compact-video-renderer:hover ytd-thumbnail #thumbnail.ytd-thumbnail img,
  ytm-shorts-lockup-view-model-v2:hover .shortsLockupViewModelHostThumbnailContainer img,
  ytm-shorts-lockup-view-model:hover .shortsLockupViewModelHostThumbnailContainer img {
    transform: scale(1.035) !important;
  }

  ytd-video-preview,
  #video-preview-container.ytd-video-preview,
  ytd-video-preview #player-container {
    background: transparent !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border-radius: var(--thumb-radius) !important;
    border: none !important;
    box-shadow: none !important;
    overflow: hidden !important;
  }

  #details.ytd-rich-grid-media,
  #details.ytd-grid-video-renderer,
  #details.ytd-rich-grid-slim-media,
  .details.ytd-compact-video-renderer,
  .yt-lockup-metadata-view-model-wiz,
  .shortsLockupViewModelHostOutsideMetadata,
  .shortsLockupViewModelHostMetadataContainer {
    background: transparent !important;
    backdrop-filter: none !important;
    border: none !important;
    box-shadow: none !important;
    padding: 10px 12px 12px 12px !important;
    margin: 0 !important;
    box-sizing: border-box !important;
  }

  yt-collections-stack > div,
  ytd-playlist-thumbnail #stacked-thumbnails > div {
    background: var(--liquid-card-gradient) !important;
    border-radius: var(--thumb-radius) var(--thumb-radius) 0 0 !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
  }

  ytd-thumbnail-overlay-time-status-renderer,
  ytd-thumbnail-overlay-toggle-button-renderer,
  badge-shape.yt-badge-shape--thumbnail-default,
  .yt-badge-shape--thumbnail-badge {
    background: rgba(12, 13, 16, 0.84) !important;
    border-radius: 6px !important;
    border: none !important;
    box-shadow: inset 0 1px 0 0 rgba(255, 250, 242, 0.30) !important;
  }

  /* --- 5. SHORTS PLAYER & 3D ACTION SPHERES --- */
  ytd-shorts #cinematics,
  ytd-reel-video-renderer #cinematics,
  #cinematics.ytd-reel-video-renderer,
  #cinematics-container,
  .cinematics-container,
  .reel-video-in-sequence-thumbnail {
    display: none !important;
    opacity: 0 !important;
    background: transparent !important;
  }

  ytd-shorts,
  .ytd-shorts,
  #shorts-container.ytd-shorts,
  #shorts-inner-container.ytd-shorts,
  #anchored-panel.ytd-shorts,
  ytd-reel-video-renderer,
  .reel-video-in-sequence,
  .reel-video-in-sequence-new,
  #reel-video-renderer,
  .player-wrapper.ytd-reel-video-renderer,
  #player-container.ytd-reel-video-renderer,
  ytd-reel-player-overlay-renderer,
  ytd-reel-player-header-renderer,
  .reel-player-header-renderer,
  .ytPlayerOverlayVideoDetailsRendererHost,
  .ytShortsVideoTitleViewModelHost,
  ytd-reel-video-renderer #overlay,
  .navigation-container.ytd-shorts,
  .ytp-chrome-top {
    background: transparent !important;
    background-color: transparent !important;
    background-image: none !important;
    box-shadow: none !important;
    border: none !important;
  }

  ytd-reel-video-renderer .html5-video-player {
    border-radius: var(--panel-radius) !important;
    box-shadow: var(--liquid-popup-depth) !important;
    overflow: hidden !important;
  }

  ytd-reel-player-overlay-renderer #actions button,
  ytd-reel-player-overlay-renderer #actions .yt-spec-button-shape-next,
  reel-action-bar-view-model button,
  reel-action-bar-view-model .yt-spec-button-shape-next,
  ytd-shorts .yt-spec-button-shape-next--overlay,
  ytd-shorts .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal,
  #navigation-button-down.ytd-shorts button,
  #navigation-button-up.ytd-shorts button,
  #navigation-button-down.ytd-shorts .yt-spec-button-shape-next,
  #navigation-button-up.ytd-shorts .yt-spec-button-shape-next {
    background-color: rgba(24, 24, 28, 0.45) !important;
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    background-position: 0% 0% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border-radius: 50% !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition:
      transform 0.22s cubic-bezier(0.16, 1, 0.3, 1),
      background-position 0.38s ease,
      box-shadow 0.22s ease !important;
  }

  ytd-reel-player-overlay-renderer #actions button:hover,
  ytd-reel-player-overlay-renderer #actions .yt-spec-button-shape-next:hover,
  reel-action-bar-view-model button:hover,
  reel-action-bar-view-model .yt-spec-button-shape-next:hover,
  ytd-shorts .yt-spec-button-shape-next--overlay:hover,
  ytd-shorts .yt-spec-button-shape-next--mono.yt-spec-button-shape-next--tonal:hover,
  #navigation-button-down.ytd-shorts button:hover,
  #navigation-button-up.ytd-shorts button:hover,
  #navigation-button-down.ytd-shorts .yt-spec-button-shape-next:hover,
  #navigation-button-up.ytd-shorts .yt-spec-button-shape-next:hover {
    transform: translateY(-2px) scale(1.04) !important;
    background-position: 100% 100% !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  /* --- 6. FILTER CHIPS & WATCH HISTORY SIDEBAR --- */
  #scroll-container.ytd-feed-filter-chip-bar-renderer,
  yt-chip-cloud-renderer {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
    margin: 0 !important;
  }

  #left-arrow.ytd-feed-filter-chip-bar-renderer::after,
  #right-arrow.ytd-feed-filter-chip-bar-renderer::before,
  #left-arrow.yt-chip-cloud-renderer::after,
  #right-arrow.yt-chip-cloud-renderer::before,
  #left-arrow-button,
  #right-arrow-button {
    background: transparent !important;
    -webkit-mask-image: none !important;
    mask-image: none !important;
  }

  yt-chip-cloud-chip-renderer,
  chip-view-model {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  .ytChipShapeChip,
  yt-chip-cloud-chip-renderer #chip-container {
    background-color: rgba(24, 25, 30, 0.56) !important;
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    background-position: 0% 0% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border-radius: 10px !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
    transition:
      transform 0.22s cubic-bezier(0.16, 1, 0.3, 1),
      box-shadow 0.22s ease,
      background-position 0.38s ease !important;
  }

  .ytChipShapeChip:hover,
  yt-chip-cloud-chip-renderer:hover #chip-container {
    transform: translateY(-2px) !important;
    background-position: 100% 100% !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  .ytChipShapeActive,
  yt-chip-cloud-chip-renderer[selected] .ytChipShapeChip,
  yt-chip-cloud-chip-renderer[selected] #chip-container {
    background: linear-gradient(135deg, #ffffff 0%, #e6e3de 100%) !important;
    color: #050507 !important;
    box-shadow:
      inset 0 1.5px 1px #ffffff,
      0 6px 18px rgba(255, 250, 240, 0.28) !important;
  }

  ytd-browse-feed-actions-renderer,
  ytd-secondary-search-container-renderer {
    background: transparent !important;
    background-image: none !important;
    backdrop-filter: none !important;
    -webkit-backdrop-filter: none !important;
    border: none !important;
    box-shadow: none !important;
    padding: 0 !important;
  }

  ytd-search-box-renderer {
    background-color: rgba(20, 21, 26, 0.52) !important;
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border-radius: 2em !important;
    border: none !important;
    box-shadow: var(--liquid-3d-rest) !important;
    padding: 2px 16px !important;
    margin-bottom: 12px !important;
    transition: box-shadow 0.25s ease, background-position 0.4s ease !important;
  }

  ytd-search-box-renderer:hover,
  ytd-search-box-renderer:focus-within {
    background-position: 100% 100% !important;
    box-shadow: var(--liquid-3d-hover) !important;
  }

  ytd-search-box-renderer #search-input,
  ytd-search-box-renderer tp-yt-paper-input,
  ytd-search-box-renderer tp-yt-paper-input-container,
  ytd-search-box-renderer .unfocused-line,
  ytd-search-box-renderer .focused-line,
  ytd-search-box-renderer #underline,
  tp-yt-paper-input-container #underline,
  tp-yt-paper-input-container .unfocused-line,
  tp-yt-paper-input-container .focused-line {
    background: transparent !important;
    border: none !important;
    border-bottom: none !important;
    box-shadow: none !important;
  }

  ytd-search-box-renderer .unfocused-line,
  ytd-search-box-renderer .focused-line,
  ytd-search-box-renderer #underline {
    display: none !important;
  }

  /* --- 7. UNIFIED ONE-PIECE 3D TOP SEARCH BAR --- */
  yt-searchbox,
  .ytSearchboxComponentHost,
  #search-form.ytd-searchbox {
    background: transparent !important;
    border: none !important;
    box-shadow: none !important;
  }

  #container.ytd-searchbox,
  .ytSearchboxComponentInputBox {
    background-color: rgba(20, 21, 26, 0.62) !important;
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    background-position: 0% 0% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border: none !important;
    border-radius: 2em 0 0 2em !important;
    box-shadow:
      inset 0 1.5px 1px 0 rgba(255, 252, 245, 0.42),
      inset 0 -1px 1px 0 rgba(255, 248, 238, 0.08),
      inset 1px 0 0 0 rgba(255, 248, 238, 0.18),
      0 8px 20px -4px rgba(0, 0, 0, 0.65) !important;
    transition: box-shadow 0.25s ease, background-position 0.4s ease !important;
  }

  #search-icon-legacy.ytd-searchbox,
  .ytSearchboxComponentSearchButton {
    background-color: rgba(30, 31, 38, 0.66) !important;
    background-image: var(--liquid-card-gradient) !important;
    background-size: 200% 200% !important;
    background-position: 100% 0% !important;
    backdrop-filter: var(--liquid-blur-sm) !important;
    -webkit-backdrop-filter: var(--liquid-blur-sm) !important;
    border: none !important;
    border-left: 1px solid rgba(255, 250, 242, 0.10) !important;
    border-radius: 0 2em 2em 0 !important;
